register_both:
require __DIR__ . '/vendor/autoload.php';

use WebCommander\Client\ClientRegistry;
use WebCommander\Config\AuthConfig;
use WebCommander\Config\SdkConfig;

$auth = new AuthConfig(
    baseUrl: (string) getenv('WC_BASE_URL'),
    clientId: (string) getenv('WC_CLIENT_ID'),
    clientSecret: (string) getenv('WC_CLIENT_SECRET'),
    clientName: 'default',
    grantType: 'client_credentials',
    authBaseUrl: (string) getenv('WC_AUTH_BASE_URL'),
);
$legacyAuth = new AuthConfig(
    baseUrl: (string) getenv('WC_LEGACY_BASE_URL'),
    clientId: (string) getenv('WC_LEGACY_CLIENT_ID'),
    clientSecret: (string) getenv('WC_LEGACY_CLIENT_SECRET'),
    redirectUri: (string) getenv('WC_LEGACY_REDIRECT_URI'),
    authString: (string) getenv('WC_LEGACY_AUTH_STRING'),
    clientName: 'legacy',
    grantType: 'client_credentials',
);

ClientRegistry::registerInstances([
    new SdkConfig($auth, raiseOnError: true),
    new SdkConfig($legacyAuth, raiseOnError: true),
]);

$client = ClientRegistry::buildClient();
$legacyClient = ClientRegistry::buildClient('legacy');
